import{_ as i,o as a,c as n,a0 as s}from"./chunks/framework.C3yZ6M33.js";const m=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),t={name:"explanation/decisions.md"};function o(r,e,l,c,d,h){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite: the load-bearing decisions, each with the alternative it beat and the consequence it carries. The full history — dozens of ADRs — lives in <code>project/adrs/</code> in the repo; read those before changing engine semantics.</p><h2 id="policy-over-mechanism" tabindex="-1">Policy over mechanism <a class="header-anchor" href="#policy-over-mechanism" aria-label="Permalink to &quot;Policy over mechanism&quot;">​</a></h2><p><strong>Decision:</strong> peregrin decides <em>who/when/where</em> a session action happens; sepia does things <em>to</em> sessions. The node spawns <code>sepia serve</code> and drives it over ndjson JSON-RPC — no <code>sepia-session</code> type is ever linked into orchestration code.</p><ul><li><em>Alternative:</em> fold session mechanism into peregrin, or have peregrin link sepia internals.</li><li><em>Consequence:</em> the boundary is a wire protocol with a manifest handshake; either side can rev independently. Cost: a subprocess hop on every session op, and <code>LocalPlane</code> exists only for dev.</li></ul><h2 id="entities-as-the-integration-seam" tabindex="-1">Entities as the integration seam <a class="header-anchor" href="#entities-as-the-integration-seam" aria-label="Permalink to &quot;Entities as the integration seam&quot;">​</a></h2><p><strong>Decision:</strong> sessions and campaigns register as generic <code>{id,kind,indexDoc}</code> entities with namespaced ops and opaque snapshots on hypha&#39;s substrate; peregrin never names a sepia type in substrate code (<code>project/adrs/0091</code> is the contract).</p><ul><li><em>Alternative:</em> bespoke session/campaign tables inside the node.</li><li><em>Consequence:</em> one sync/lock/outbox machinery serves both planes; new kinds are registrations, not migrations.</li></ul><h2 id="latest-wins-queue" tabindex="-1">Latest-wins queue <a class="header-anchor" href="#latest-wins-queue" aria-label="Permalink to &quot;Latest-wins queue&quot;">​</a></h2><p><strong>Decision:</strong> runs on the same <code>{repo}:{ref}</code> key supersede — a newer push cancels the in-flight run rather than queueing behind it.</p><ul><li><em>Alternative:</em> FIFO queueing of every event.</li><li><em>Consequence:</em> stale work never lands, at the cost of needing explicit cancellation plumbing through drivers.</li></ul><h2 id="capabilities-not-ambient-trust" tabindex="-1">Capabilities, not ambient trust <a class="header-anchor" href="#capabilities-not-ambient-trust" aria-label="Permalink to &quot;Capabilities, not ambient trust&quot;">​</a></h2><p><strong>Decision:</strong> campaigns declare <code>capabilities:</code>; secrets resolve by NAME through a per-campaign grant (<code>capabilities.secrets</code>), and an unresolvable name fails the node.</p><ul><li><em>Alternative:</em> inherit the operator&#39;s full environment.</li><li><em>Consequence:</em> AI-governed workflows are bounded by construction — see <a href="./safety.html">Safety</a> and <a href="./threat-model.html">Threat model</a>.</li></ul><h2 id="yaml-campaigns-as-plugins" tabindex="-1">YAML campaigns as plugins <a class="header-anchor" href="#yaml-campaigns-as-plugins" aria-label="Permalink to &quot;YAML campaigns as plugins&quot;">​</a></h2><p><strong>Decision:</strong> workflows are YAML files distributed as tamias bundles (<code>peregrin-bundle</code>), with <code>include</code>/snippet resolution for composition — no compiled workflow format.</p><ul><li><em>Alternative:</em> a typed workflow DSL compiled to Rust.</li><li><em>Consequence:</em> campaigns are data, reviewable in diffs and editable without a toolchain; validation moves to <code>campaign validate</code> and the loader. See <a href="./plugins.html">Plugins</a>.</li></ul>',17)])])}const u=i(t,[["render",o]]);export{m as __pageData,u as default};
